scwin.checkVal = function() {
    return window.getComputedStyle(document.getElementsByClassName('w2editablePivot_cell type12 pvtTotal colTotal')[0]).getPropertyValue('text-Align') == 'right';
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 하단의 합계영역의 값이 우측정렬되어 보여지는지를 확인한다.
    //1. After executing the sample, make sure that the value of the total area at the bottom is displayed on the right side.
    //Verify step 1. The value of the sum area is shown right.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
